+using TextKit.Core;
+
+namespace TextKit.Tests.Core;
+
+public class AppTests
+{
+    [Theory]
+    [InlineData()]
+    [InlineData("help")]
+    [InlineData("--help")]
+    [InlineData("-h")]
+    public void HelpIsOrderedAndPadded(params string[] args)
+    {
+        ICommand[] commands =
+        [
+            new FakeCommand("zulu", "zulu <file>", "Last"),
+            new FakeCommand("alpha", "alpha <file> <text>", "First"),
+        ];
+        using var output = new StringWriter { NewLine = "\n" };
+        using var error = new StringWriter { NewLine = "\n" };
+
+        var result = App.Run(args, commands, output, error);
+
+        Assert.Equal(ExitCodes.Ok, result);
+        Assert.Equal("Usage: textkit <command> [arguments]\n\nCommands:\n" +
+                     "  alpha <file> <text>   First\n" +
+                     "  zulu <file>           Last\n", output.ToString());
+        Assert.Equal("", error.ToString());
+    }
+
+    [Fact]
+    public void DispatchesRemainingArgumentsAndReturnsCommandResult()
+    {
+        var command = new FakeCommand("upper", "upper <file>", "Print", ExitCodes.Input);
+        using var output = new StringWriter { NewLine = "\n" };
+        using var error = new StringWriter { NewLine = "\n" };
+
+        var result = App.Run(["upper", "a.txt", "extra"], [command], output, error);
+
+        Assert.Equal(ExitCodes.Input, result);
+        Assert.Equal(new[] { "a.txt", "extra" }, command.ReceivedArgs);
+        Assert.Same(output, command.ReceivedOutput);
+        Assert.Equal("", error.ToString());
+    }
+
+    [Fact]
+    public void CommandNamesAreCaseSensitive()
+    {
+        var command = new FakeCommand("upper", "upper <file>", "Print");
